let bestItem = null;

for (let i = 0; i < items.length; i++) {
  const bin = items[i]?.binary?.data;
  if (!bin) continue;

  const size = bin.fileSize ?? 0;
  const mime = bin.mimeType ?? '';

  // só pega áudio válido
  if (!mime.startsWith('audio/')) continue;
  if (size < 100) continue;

  // escolhe o maior (evita o quebrado de 9B)
  if (!bestItem || size > (bestItem.binary.data.fileSize ?? 0)) {
    bestItem = items[i];
  }
}

if (!bestItem) return [];

// garante que o binário está no campo "data" (que o OpenAI espera)
return [{
  json: bestItem.json ?? {},
  binary: {
    data: bestItem.binary.data
  }
}];

