const items = $input.all();

// ✅ Quais tags devem "passar" (qualquer uma delas)
const PASSA_SE_TIVER_QUALQUER = [
  "FGTS",
  "INSS",
  "SIMPLES NACIONAL",
  "PIS E COFINS",
  "CSLL E IRPJ",
  "CLIENTES CONTABILIDADE",
  "LEAD",
];

// ✅ Se quiser exigir os dois ao mesmo tempo:
const EXIGE_FGTS_E_INSS = false; // true = só passa quem tiver FGTS e INSS

function normalizeTags(raw) {
  if (!raw) return [];

  if (typeof raw === "string") {
    return raw
      .split(/[;,|]/g)
      .map(t => t.trim())
      .filter(Boolean);
  }

  if (Array.isArray(raw)) {
    return raw
      .map(t => (typeof t === "string" ? t.trim() : t?.name || t?.label || t?.title))
      .filter(Boolean);
  }

  if (typeof raw === "object") {
    return normalizeTags(raw.tags || raw.labels || raw.data || raw.items || raw.results);
  }

  return [];
}

function pickName(j) {
  return (
    j?.dataBlock?.name ||
    j?.dataBlock?.internalName ||
    j?.pushname ||
    j?.name ||
    j?.internalName ||
    j?.alternativeName ||
    ""
  );
}

function pickNumber(j) {
  const n = j?.data?.number || j?.number || j?.phone || j?.idFromService || "";
  return String(n || "").replace(/\D/g, "");
}

function upperTags(arr) {
  return (arr || []).map(t => String(t).trim().toUpperCase()).filter(Boolean);
}

const result = items.map((item) => {
  const j = item.json || {};

  // ✅ pega tags de vários lugares (inclui label também)
  const tagsRaw = normalizeTags(
    j?.tags ||
    j?.dataBlock?.tags ||
    j?.dataBlock?.labels ||
    j?.labels ||
    j?.label
  );

  const tagsUpper = upperTags(tagsRaw);

  const has = (t) => tagsUpper.includes(String(t).toUpperCase());

  const tagFlags = {
    INSS: has("INSS"),
    "Simples Nacional": has("SIMPLES NACIONAL"),
    FGTS: has("FGTS"),
  };

  const hasAnyWanted = PASSA_SE_TIVER_QUALQUER.some(t => has(t));

  return {
    json: {
      contactId: j?.contactId ?? j?.id ?? null,
      serviceId: j?.serviceId ?? null,
      ticketId: j?.ticketId ?? j?.currentTicketId ?? null,
      name: pickName(j),
      number: pickNumber(j),
      unread: j?.unread ?? j?.data?.unread ?? null,
      lastMessageAt: j?.lastMessageAt ?? j?.lastMessageAtIso ?? j?.lastSyncAt ?? null,
      tags: tagsRaw,
      label: tagsRaw.join(" | "),
      tagFlags,
      // debug opcional
      _hasAnyWanted: hasAnyWanted,
    }
  };
});

// ✅ aplica o filtro
const filtered = result.filter(it => {
  const f = it.json.tagFlags || {};
  if (EXIGE_FGTS_E_INSS) return f.FGTS && f.INSS;

  // passa quem tiver qualquer tag da lista
  return it.json._hasAnyWanted === true;
});

// remove debug
filtered.forEach(it => delete it.json._hasAnyWanted);

return filtered;

const items = $input.all();

function normalizeTags(raw) {
  if (!raw) return [];

  if (typeof raw === "string") {
    return raw
      .split(/[;,|]/g)
      .map(t => t.trim())
      .filter(Boolean);
  }

  if (Array.isArray(raw)) {
    return raw
      .map(t => (typeof t === "string" ? t.trim() : t?.name || t?.label || t?.title))
      .filter(Boolean);
  }

  if (typeof raw === "object") {
    return normalizeTags(raw.tags || raw.labels || raw.data || raw.items || raw.results);
  }

  return [];
}

function pickName(j) {
  return (
    j?.dataBlock?.name ||
    j?.dataBlock?.internalName ||
    j?.pushname ||
    j?.name ||
    j?.internalName ||
    j?.alternativeName ||
    ""
  );
}

function pickNumber(j) {
  const n = j?.data?.number || j?.number || j?.phone || j?.idFromService || "";
  return String(n || "").replace(/\D/g, ""); // deixa só números
}

return items.map((item) => {
  const j = item.json;

  // tags
  const tags = normalizeTags(
    j?.tags ||
    j?.dataBlock?.tags ||
    j?.dataBlock?.labels ||
    j?.labels
  );

  const has = (t) => tags.includes(t);

  return {
    json: {
      contactId: j?.contactId ?? j?.id ?? null,
      serviceId: j?.serviceId ?? null,
      ticketId: j?.ticketId ?? j?.currentTicketId ?? null,

      // ✅ novo: nome + número
      name: pickName(j),
      number: pickNumber(j),

      // ✅ bons pra usar depois, sem poluir
      unread: j?.unread ?? j?.data?.unread ?? null,
      lastMessageAt: j?.lastMessageAt ?? j?.lastMessageAtIso ?? j?.lastSyncAt ?? null,

      // ✅ tags prontas
      tags,
      label: tags.join(" | "),
      tagFlags: {
        INSS: has("INSS"),
        "Simples Nacional": has("Simples Nacional"),
        FGTS: has("FGTS"),
      },
    }
  };
});

// ===== CONFIGURAÇÃO =====
const LIMITE_MINUTOS = 30; // fácil de alterar
// ========================

return items.map(item => {
  const original = item.json;

  let passou30min = false;

  if (original.created_at) {
    const criadoEm = new Date(original.created_at);
    const agora = new Date();

    const diffMs = agora.getTime() - criadoEm.getTime();
    const diffMin = diffMs / (1000 * 60);

    passou30min = diffMin >= LIMITE_MINUTOS;
  }

  // remove created_at do objeto
  const { created_at, ...jsonSemCreatedAt } = original;

  return {
    json: {
      calculo: {
        passou30min
      },
      json: jsonSemCreatedAt
    }
  };
});

const allTickets = items
  .flatMap(i => i.json?.data || [])
  .filter(Boolean);

// remove duplicados por id
const uniqueMap = new Map();
for (const t of allTickets) {
  if (t?.id) uniqueMap.set(t.id, t);
}
const tickets = Array.from(uniqueMap.values());

// agrupa por contactId
const byContact = new Map();
for (const t of tickets) {
  if (!t.contactId) continue;

  if (!byContact.has(t.contactId)) {
    byContact.set(t.contactId, []);
  }

  byContact.get(t.contactId).push(t);
}

const output = [];

for (const [contactId, tks] of byContact.entries()) {
  // prioridade:
  // 1) ticket aberto
  // 2) se não tiver, pega o mais recente
  let selectedTicket = tks.find(t => t.isOpen === true);

  if (!selectedTicket) {
    selectedTicket = tks.sort((a, b) => {
      const da = new Date(a.updatedAt || a.createdAt || a.startedAt || 0).getTime();
      const db = new Date(b.updatedAt || b.createdAt || b.startedAt || 0).getTime();
      return db - da;
    })[0];
  }

  if (!selectedTicket) continue;
  if (!selectedTicket.id || !selectedTicket.departmentId) continue;

  output.push({
    json: {
      contactId,
      ticketId: selectedTicket.id,
      departmentId: selectedTicket.departmentId,
      protocol: selectedTicket.protocol ?? null,
      origin: selectedTicket.origin ?? null,
      startedAt: selectedTicket.startedAt ?? null,
      abertoFechado: selectedTicket.isOpen ?? false,
      currentTicketTransferId: selectedTicket.currentTicketTransferId ?? null,
      serviceId: selectedTicket.departmentId,
    },
  });
}

return output;

const inItems = $input.all();

const WORK_DAYS = [1, 2, 3, 4, 5];
const TIME_WINDOWS = [
  { inicio: "09:00", fim: "12:00" },
  { inicio: "14:00", fim: "18:30" },
];

const FUSO_HORAS = -4;

function horaParaMinutos(hora) {
  const s = String(hora || "").slice(0, 5);
  const [hStr, mStr] = s.split(":");
  const h = Number(hStr);
  const m = Number(mStr);
  if (!Number.isFinite(h) || !Number.isFinite(m)) return null;
  return h * 60 + m;
}

function isDentroDoHorario(horaAtualStr) {
  const atualMin = horaParaMinutos(horaAtualStr);
  if (atualMin === null) return false;

  for (const janela of TIME_WINDOWS) {
    const inicioMin = horaParaMinutos(janela.inicio);
    const fimMin = horaParaMinutos(janela.fim);
    if (inicioMin === null || fimMin === null) continue;
    if (atualMin >= inicioMin && atualMin <= fimMin) return true;
  }
  return false;
}

return inItems.map(item => {
  const original = item.json || {};

  // pega a melhor data disponível
  const baseTime =
    original.time_ultima_mensagem ||
    original.startedAt ||
    original.created_at ||
    null;

  let ultimaMsgLocalISO = null;
  let diaUtil = false;

  if (baseTime) {
    const utc = new Date(baseTime);
    if (!isNaN(utc.getTime())) {
      const local = new Date(utc);
      local.setHours(local.getHours() + FUSO_HORAS);
      ultimaMsgLocalISO = local.toISOString();
      diaUtil = WORK_DAYS.includes(local.getDay());
    }
  }

  // se não vier hora_atual, usa o relógio atual do n8n (já com fuso aplicado)
  let horaAtualStr = original.hora_atual;
  if (!horaAtualStr) {
    const now = new Date();
    now.setHours(now.getHours() + FUSO_HORAS);
    horaAtualStr = now.toISOString().slice(11, 16); // "HH:mm"
  }

  const dentroHorario = diaUtil && isDentroDoHorario(horaAtualStr);

  return {
    json: {
      ...original,
      time_base_usada: baseTime,
      hora_atual_usada: horaAtualStr,
      time_ultima_mensagem_ajustada: ultimaMsgLocalISO,
      dia_util: diaUtil,
      dentro_do_horario: dentroHorario,
    }
  };
});

// Gera um atraso aleatório entre 20s e 80s para CADA item
const MIN_S = 60;      // 20 segundos
const MAX_S = 100;      // 1 min 20s

for (const item of items) {
  const s = Math.floor(MIN_S + Math.random() * (MAX_S - MIN_S + 1));
  item.json.delaySeconds = s;        // ex.: 37
  item.json.delayMs = s * 1000;      // ex.: 37000
  item.json.delayHuman = `${s}s`;    // útil para logs/debug
}

return items;

const dados = $input.first().json.data || [];

return dados.map(c => {

  const numero = c.data?.number || null;
  const jid = c.data?.jidId || null;

  return {
    json: {
      id: c.id,

      nome: c.name || c.alternativeName || c.internalName || "Sem nome",

      numero,
      jid,


      // mensagens
      ultimaMensagemAt: c.lastMessageAt || null,
      ultimaMensagemId: c.lastMessageId || null,

    }
  };
});

const itens = $input.all();
const agora = new Date();

const vistos = new Set();

return itens
  .map(item => {
    const c = item.json;
    const numero = c.data?.number || null;
    const jid = c.data?.jidId || null;

    let minutos = 0;
    let passou30min = false;

    if (c.lastMessageAt) {
      const ultima = new Date(c.lastMessageAt);
      minutos = Math.floor((agora - ultima) / 1000 / 60);
      passou30min = minutos >= 30;
    }

    return {
      json: {
        contatoId: c.id || null,
        nome: c.name || null,
        numero,
        jid,
        tipo: c.isGroup ? "grupo" : "individual",
        status: c.status || null,
        naoLidas: c.unread || 0,
        ultimaMensagemAt: c.lastMessageAt || null,
        ticketAtualId: c.currentTicketId || null,
        temTicketAtual: !!c.currentTicketId,
        departamentoPadraoId: c.defaultDepartmentId || null,
        serviceId: c.serviceId || null,
        accountId: c.accountId || null,
        minutosSemResposta: minutos,
        passou30min
      }
    };
  })
  .filter(item => {
    const ticketId = item.json.ticketAtualId;
    if (!ticketId) return false;
    if (vistos.has(ticketId)) return false;
    vistos.add(ticketId);
    return true;
  });

const items = $input.all();

const output = [];

for (const item of items) {
  const data = item.json.data;

  if (Array.isArray(data)) {
    for (const ticket of data) {
      output.push({
        json: ticket
      });
    }
  }
}

return output;

const now = new Date();

for (const item of $input.all()) {
  const updatedAt = new Date(item.json.updatedAt);

  const diffMs = now - updatedAt;
  const diffMinutes = diffMs / (1000 * 60);

  item.json.passou30Min = diffMinutes >= 30;
}

return $input.all();
